package servlets.architecture;import com.google.gson.JsonObject;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.HttpServlet;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import logic.system.data.architecture.ArchitectureManager;import logic.system.programs.selectedProg.SelectedProgramManager;import logic.system.updates.UpdateFlagsManager;import servlets.utils.JsonResponseUtils;import servlets.utils.ResponseWriter;import servlets.utils.ServletUserUtils;import java.io.IOException;@WebServlet("/setArchitecture")public class SetArchitectureServlet extends HttpServlet {    @Override    protected void doPost(HttpServletRequest req, HttpServletResponse res) throws IOException {        String username = ServletUserUtils.getUsernameFromCookies(req);        if (username == null) {            ResponseWriter.write(res, JsonResponseUtils.error("No active session."));            return;        }        String progName = SelectedProgramManager.getSelectedProgram(username);        if (progName == null) {            ResponseWriter.write(res, JsonResponseUtils.error("No selected program."));            return;        }        String selected = req.getParameter("architecture");        if (selected == null || selected.isBlank()) {            ResponseWriter.write(res, JsonResponseUtils.error("Missing architecture."));            return;        }        ArchitectureManager.setArchitecture(username, progName,selected);        UpdateFlagsManager.markUpdated("architectureSummary",username);        JsonObject response = JsonResponseUtils.success("Architecture updated to " + selected);        ResponseWriter.write(res, response);    }}